function validate([n, left, right]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n must be between 1 and 10^4.';
  if (left.length + right.length < 1) return 'There must be at least one ant.';
  if (left.length + right.length > n + 1) return 'There can be at most n + 1 ants.';
  const seen = new Set();
  for (const p of [...left, ...right]) {
    if (!Number.isInteger(p) || p < 0 || p > n) return 'Every position must be between 0 and n.';
    if (seen.has(p)) return 'Each position may hold only one ant.';
    seen.add(p);
  }
  return null;
}

