function getLastMoment(n, left, right) {
  // Simulate in half-unit steps (positions doubled) so every meeting happens on a grid point.
  let ants = [...left.map(p => ({ pos: 2 * p, dir: -1 })), ...right.map(p => ({ pos: 2 * p, dir: 1 }))];
  let tick = 0, last = 0;
  while (ants.length > 0) {
    const staying = [];
    for (const ant of ants) {
      if ((ant.pos === 0 && ant.dir === -1) || (ant.pos === 2 * n && ant.dir === 1)) last = tick / 2;
      else staying.push(ant);
    }
    ants = staying;
    for (const ant of ants) ant.pos += ant.dir;
    const byPos = new Map();
    for (const ant of ants) {
      if (!byPos.has(ant.pos)) byPos.set(ant.pos, []);
      byPos.get(ant.pos).push(ant);
    }
    for (const group of byPos.values()) if (group.length === 2) for (const ant of group) ant.dir = -ant.dir;
    tick++;
  }
  return last;
}

