function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const positions = Array.from({ length: n + 1 }, (_, i) => i);
  let leftCount, rightCount;
  if (size === 'large') {
    leftCount = Math.floor(rand() * 2001);
    rightCount = Math.floor(rand() * 2001);
  } else {
    const total = 1 + Math.floor(rand() * (n + 1));
    leftCount = Math.floor(rand() * (total + 1));
    rightCount = total - leftCount;
  }
  if (leftCount + rightCount === 0) leftCount = 1;
  const total = leftCount + rightCount;
  // Partial Fisher-Yates shuffle picks distinct positions.
  for (let i = 0; i < total; i++) {
    const j = i + Math.floor(rand() * (positions.length - i));
    [positions[i], positions[j]] = [positions[j], positions[i]];
  }
  return [n, positions.slice(0, leftCount), positions.slice(leftCount, total)];
}
